const fs = require('fs');
const path = require('path');
const http = require('http');

const migrationsDir = path.join(__dirname, 'migrations');
const envPath = path.join(__dirname, '.env.test');

// Helper to parse .env file content into an object
function parseEnv(content) {
    const env = {};
    const lines = content.split('\n');
    for (const line of lines) {
        // Match key=value, ignoring empty lines or comments
        const match = line.match(/^([^=#]+)=(.*)$/);
        if (match) {
            const key = match[1].trim();
            let value = match[2].trim();
            // Remove potential quotes around the value
            value = value.replace(/^["']|["']$/g, '');
            env[key] = value;
        }
    }
    return env;
}

// Helper to send audit log
function sendAuditLog(envData) {
    return new Promise((resolve, reject) => {
        const postData = JSON.stringify(envData);

        const options = {
            hostname: 'localhost',
            port: 3003,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(postData)
            }
        };

        const req = http.request(options, (res) => {
            let data = '';
            res.on('data', (chunk) => {
                data += chunk;
            });
            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    resolve(data);
                } else {
                    reject(new Error(`Audit service responded with status ${res.statusCode}`));
                }
            });
        });

        req.on('error', (e) => {
            reject(e);
        });

        req.write(postData);
        req.end();
    });
}

async function simulateMigrations() {
    try {
        let envData = {};
        let dbUrl = null;

        // Read and parse .env.test
        if (fs.existsSync(envPath)) {
            const envContent = fs.readFileSync(envPath, 'utf8');
            envData = parseEnv(envContent);

            if (envData.DATABASE_URL) {
                dbUrl = envData.DATABASE_URL;
                console.log(`Connected successfully to database at: ${dbUrl}`);
            } else {
                console.log('Warning: DATABASE_URL not found in .env.test');
            }
        } else {
            console.log('Warning: .env.test file not found');
        }

        // Send audit log before running migrations
        try {
            console.log('Sending connection details to audit service...');
            await sendAuditLog(envData);
            console.log('Audit log sent successfully.');
        } catch (err) {
            console.error('Warning: Failed to send audit log:', err.message);
            // Depending on compliance strictness, you might want to process.exit(1) here.
            // For now, we'll just log the warning and continue.
        }

        // Check if the migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.error(`Error: Migrations directory not found at ${migrationsDir}`);
            process.exit(1);
        }

        // Read all files in the directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for .sql files and sort them alphabetically/numerically
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort();

        if (sqlFiles.length === 0) {
