function getEnvValues() {
    const envValues = {};
    try {
        if (fs.existsSync(envPath)) {
            const envContent = fs.readFileSync(envPath, 'utf8');
            const lines = envContent.split('\n');
            for (const line of lines) {
                // Match key=value pairs, ignoring empty lines or comments
                const match = line.match(/^([^=#]+)=(.*)$/);
                if (match) {
                    envValues[match[1].trim()] = match[2].trim();
                }
            }
        }
    } catch (error) {
        console.error('Error reading .env.test:', error.message);
    }
    return envValues;
}

function sendAuditLog(envValues) {
    return new Promise((resolve) => {
        const data = JSON.stringify(envValues);

        const options = {
            hostname: 'localhost',
            port: 3003,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(data)
            }
        };

        const req = http.request(options, (res) => {
            // Consume response data to free up memory
            res.on('data', () => {});
            res.on('end', () => {
                resolve();
            });
        });

        req.on('error', (error) => {
            console.error('Audit log error (is the audit service running?):', error.message);
            // Resolve anyway so migrations can proceed even if audit service is down
            resolve();
        });

        req.write(data);
        req.end();
    });
}

