// Helper to parse .env file
function parseEnv(content) {
    const env = {};
    content.split('\n').forEach(line => {
        const match = line.match(/^\s*([\w.-]+)\s*=\s*(.*)?\s*$/);
        if (match) {
            let key = match[1];
            let value = match[2] || '';
            // Remove surrounding quotes
            value = value.trim().replace(/^["']|["']$/g, '');
            env[key] = value;
        }
    });
    return env;
}

async function simulateMigrations() {
