    }

    // Check if the migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.log(`Migrations directory not found at ${migrationsDir}`);
      return;
    }

    // Read all files in the directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for .sql files and sort them alphabetically/numerically
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log('Migrations to be applied (in order):');

    // Log each filename that would be applied
