        if (trimmedLine && !trimmedLine.startsWith('#')) {
          const match = trimmedLine.match(/^([^=]+)=(.*)$/);
          if (match) {
            envVars[match[1].trim()] = match[2].trim();
          }
        }
      }
    }

    // Send connection details to the migration audit service
    try {
      console.log('Sending audit log to http://localhost:3003/api/audit...');
