        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(envVars)
      });

      if (!response.ok) {
        console.error(`Audit service responded with status: ${response.status}`);
      } else {
        console.log('Audit log sent successfully.');
      }
    } catch (auditError) {
      console.error('Failed to send audit log:', auditError.message);
    }

