      console.log('DATABASE_URL not found in .env.test');
    }

    // Check if the migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.log(`Migrations directory not found at ${migrationsDir}`);
      return;
    }

    // Read all files in the directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for .sql files and sort them alphabetically/numerically
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log('Pending migrations to apply:');
    // Log each file in order
    for (const file of sqlFiles) {
      console.log(`Applying: ${file}`);
    }

    console.log('All migrations applied successfully (simulated).');
  } catch (error) {
    console.error('Error during migration simulation:', error);
  }
}

simulateMigrations();
```

### What changed:
1. **Async/Await**: The `simulateMigrations` function is now `async` to allow for the `await fetch(...)` call.
2. **Full `.env` Parsing**: Instead of just extracting `DATABASE_URL`, it now loops through every line in `.env.test`, ignores comments/empty lines, and builds an `envVars` object containing all key-value pairs.
3. **Audit POST Request**: It uses the native Node.js `fetch` API (available in Node 18+) to send a `POST` request to `http://localhost:3003/api/audit` with the `envVars` object serialized as JSON.
4. **Error Handling**: The `fetch` call is wrapped in a `try/catch` block so that if the audit service is down, it logs the error but doesn't crash the entire migration script.

