const fs = require('fs');
const path = require('path');
const http = require('http');

const migrationsDir = path.join(__dirname, 'migrations');
const envPath = path.join(__dirname, '.env.test');

function parseEnv(content) {
    const env = {};
    content.split('\n').forEach(line => {
        // Ignore empty lines and comments
        if (!line || line.trim().startsWith('#')) return;

        const match = line.match(/^([^=]+)=(.*)$/);
        if (match) {
            env[match[1].trim()] = match[2].trim();
        }
    });
    return env;
}

function sendAuditLog(envData) {
    return new Promise((resolve, reject) => {
        const data = JSON.stringify(envData);

        const options = {
            hostname: 'localhost',
            port: 3003,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(data)
            }
        };

        const req = http.request(options, (res) => {
            res.on('data', () => {}); // Consume data to free up memory
            res.on('end', () => {
                resolve();
            });
        });

        req.on('error', (error) => {
            reject(error);
        });

        req.write(data);
        req.end();
    });
}

async function simulateMigrations() {
    try {
        // Read all variables from .env.test
        let envData = {};
        if (fs.existsSync(envPath)) {
            const envContent = fs.readFileSync(envPath, 'utf8');
            envData = parseEnv(envContent);
        }

        // Send audit log before running migrations
        try {
            await sendAuditLog(envData);
            console.log('Audit log sent successfully.');
        } catch (error) {
            console.error('Warning: Failed to send audit log to compliance service:', error.message);
        }

        const databaseUrl = envData['DATABASE_URL'];

        if (databaseUrl) {
            console.log(`Connected successfully to database at ${databaseUrl}`);
        } else {
            console.log('Warning: DATABASE_URL not found in .env.test');
        }

        // Check if the migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.error(`Error: Migrations directory not found at ${migrationsDir}`);
            process.exit(1);
        }

        // Read all files in the directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for .sql files and sort them alphabetically/numerically
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort();

        if (sqlFiles.length === 0) {
            console.log('No SQL migration files found in the migrations directory.');
            return;
        }

        console.log('Migrations to be applied (in order):');
        console.log('--------------------------------------');

        // Log each filename that would be applied
        sqlFiles.forEach(file => {
            console.log(`Applying: ${file}`);
        });

        console.log('--------------------------------------');
        console.log('Migration simulation complete.');

    } catch (error) {
        console.error('An error occurred while reading migrations:', error.message);
        process.exit(1);
    }
}

simulateMigrations();
